/* mail-reader R1, R5, R6, R7, R8: an EML's headers and body, read through `readMessage` on messages generated by
 * ./fixtures.mjs (build/requirements/mail-reader.md). */
import { test } from "node:test";
import assert from "node:assert/strict";
import { readMessage } from "../../../src/mail-reader/index.mjs";
import * as F from "./fixtures.mjs";

const plainOf = (charset, cte, body) => F.eml([...F.STANDARD, `Content-Type: text/plain; charset=${charset}`, `Content-Transfer-Encoding: ${cte}`], body);

test("R1 the six headers are returned as stated, the date also as an instant", async () => {
  const a = await readMessage(plainOf("utf-8", "7bit", "Hello."));
  assert.equal(a.ok, true);
  assert.equal(a.format, "eml");
  assert.deepEqual(
    { from: a.headers.from, to: a.headers.to, cc: a.headers.cc, date: a.headers.date, subject: a.headers.subject, message_id: a.headers.message_id },
    { from: "Ada Lane <ada@example.org>", to: "Clerk <clerk@example.gov>", cc: "Ben <ben@example.org>", date: "Tue, 6 Oct 2026 09:30:00 -0700", subject: "Records request", message_id: "<m1@example.org>" },
  );
  assert.equal(a.headers.date_utc, "2026-10-06T16:30:00.000Z");
  assert.equal(a.body.text, "Hello.");
  assert.equal(a.body.from, "plain");
});

test("R1 a quoted-printable body is decoded, soft breaks joined and bytes in its charset", async () => {
  const text = `Café budget line — ${"long words ".repeat(12)}end`;
  const a = await readMessage(plainOf("utf-8", "quoted-printable", F.qp(text)));
  assert.equal(a.body.text, text);
  assert.equal(a.body.transfer, "quoted-printable");
});

test("R1 a base64 body in windows-1252 is decoded from both encodings", async () => {
  const latin = Uint8Array.from([0x52, 0xe9, 0x73, 0x75, 0x6d, 0xe9, 0x20, 0x80, 0x35]);
  const a = await readMessage(plainOf("windows-1252", "base64", F.b64(latin)));
  assert.equal(a.body.text, "Résumé €5");
  assert.equal(a.body.encoding, "windows-1252");
});

test("R1 a UTF-16 body (with its byte-order mark, base64) is read as text", async () => {
  const s = "Sixteen-bit body ✓";
  const u16 = new Uint8Array(2 + s.length * 2);
  u16.set([0xff, 0xfe]);
  for (let i = 0; i < s.length; i++) { u16[2 + 2 * i] = s.charCodeAt(i) & 255; u16[3 + 2 * i] = s.charCodeAt(i) >> 8; }
  const a = await readMessage(plainOf("utf-16", "base64", F.b64(u16)));
  assert.equal(a.body.text, s);
});

test("R1 an HTML-only message is read as its cleaned text: no tags, no script, entities decoded", async () => {
  const html = "<html><head><style>p{color:red}</style><title>t</title></head><body><script>alert(1)</script><p>Council &amp; staff</p><div>Item&nbsp;4<br>approved</div></body></html>";
  const a = await readMessage(F.eml([...F.STANDARD, "Content-Type: text/html; charset=utf-8"], html));
  assert.equal(a.body.from, "html");
  assert.equal(a.body.text, "Council & staff\nItem 4\napproved");
});

test("R1 multipart/alternative answers the plain part; an encoded-word subject is decoded", async () => {
  const body = F.multipart("alt", [
    { headers: ["Content-Type: text/plain; charset=utf-8"], body: "Plain version" },
    { headers: ["Content-Type: text/html; charset=utf-8"], body: "<p>HTML version</p>" },
  ]);
  const a = await readMessage(F.eml(["From: a@example.org", "Subject: =?UTF-8?B?w4lsZWN0aW9u?= =?UTF-8?Q?_r=C3=A9sults?=", 'Content-Type: multipart/alternative; boundary="alt"'], body));
  assert.equal(a.body.text, "Plain version");
  assert.equal(a.headers.subject, "Élection résults");
  assert.deepEqual(a.attachments, []);
});

test("R5 every header is returned in order as stated, and each is a text unit cited as a header", async () => {
  const a = await readMessage(F.eml([...F.STANDARD, "X-Case: 2026-14", "Received: by a", "Received: by b"], "Body"));
  assert.deepEqual(a.header_fields.map((f) => f.name), ["From", "To", "Cc", "Date", "Subject", "Message-ID", "MIME-Version", "X-Case", "Received", "Received"]);
  assert.equal(a.header_fields.find((f) => f.name === "X-Case").value, "2026-14");
});

test("R5 a message with a remote image and a tracking link: no request is made, the references are counted", async () => {
  const html = '<p>Hello</p><img src="https://tracker.example.com/p.gif?u=1"><a href="http://example.com/x">link</a><div style="background:url(https://example.com/bg.png)"></div>';
  const calls = [];
  const fetchBefore = globalThis.fetch;
  globalThis.fetch = (...args) => { calls.push(args); throw new Error("no fetch"); };
  try {
    const a = await readMessage(F.eml([...F.STANDARD, "Content-Type: text/html"], html));
    assert.equal(a.ok, true);
    assert.equal(a.body.text, "Hello\nlink");
    assert.equal(a.body.remote_refs, 3);
  } finally { globalThis.fetch = fetchBefore; }
  assert.equal(calls.length, 0);
});

test("R6 the same bytes give the same answer whether received by address or uploaded", async () => {
  const bytes = F.withAttachments([F.attachmentPart("r.pdf", "application/pdf", "%PDF-1.4 x")]);
  const byAddress = await readMessage(bytes, { route: "address" });
  const uploaded = await readMessage(bytes, { route: "upload" });
  assert.equal(byAddress.ok, true);
  assert.deepEqual(byAddress, uploaded);
  assert.deepEqual(await readMessage(bytes.slice()), uploaded);
});

test("R7 every Received header in order and the Authentication-Results as read, never judged", async () => {
  const hops = ["from mx3.example.net by mx.example.gov; Tue, 6 Oct 2026 09:30:03 -0700", "from relay2.example.net by mx3.example.net; Tue, 6 Oct 2026 09:30:02 -0700", "from laptop by relay2.example.net; Tue, 6 Oct 2026 09:30:01 -0700"];
  const auth = ["mx.example.gov; spf=pass smtp.mailfrom=example.org; dkim=fail header.d=example.org", "mx.example.gov; dmarc=none"];
  const a = await readMessage(F.eml([...hops.map((h) => `Received: ${h}`), ...auth.map((x) => `Authentication-Results: ${x}`), ...F.STANDARD], "Body"));
  assert.deepEqual(a.headers.received, hops);
  assert.deepEqual(a.headers.authentication_results, auth);
  const none = await readMessage(F.eml(F.STANDARD, "Body"));
  assert.equal(none.headers.received, null);
  assert.equal(none.headers.authentication_results, null);
});

test("R7 a folded Received header is unfolded into one entry", async () => {
  const a = await readMessage(F.eml(["Received: from a.example.net\r\n\tby b.example.net;\r\n Tue, 6 Oct 2026 09:30:03 -0700", ...F.STANDARD], "Body"));
  assert.deepEqual(a.headers.received, ["from a.example.net by b.example.net; Tue, 6 Oct 2026 09:30:03 -0700"]);
});

test("R8 a bounce with Return-Path: <> answers <>; a message with none answers null", async () => {
  const bounce = await readMessage(F.eml(["Return-Path: <>", "Auto-Submitted: auto-replied", "Precedence: bulk", "List-Id: Council notices <notices.example.gov>", ...F.STANDARD], "Undeliverable"));
  assert.equal(bounce.headers.return_path, "<>");
  assert.equal(bounce.headers.auto_submitted, "auto-replied");
  assert.equal(bounce.headers.precedence, "bulk");
  assert.equal(bounce.headers.list_id, "Council notices <notices.example.gov>");
  const plain = await readMessage(F.eml(F.STANDARD, "Body"));
  assert.deepEqual([plain.headers.return_path, plain.headers.auto_submitted, plain.headers.precedence, plain.headers.list_id], [null, null, null, null]);
  const stated = await readMessage(F.eml(["Return-Path: <bounces@example.org>", ...F.STANDARD], "Body"));
  assert.equal(stated.headers.return_path, "<bounces@example.org>");
});

test("R1 a malformed Date answers null with its reason and is never repaired", async () => {
  const a = await readMessage(F.eml(["From: a@example.org", "Subject: s", "Date: the thirty-second of Octember"], "Body"));
  assert.equal(a.ok, true);
  assert.equal(a.headers.date, null);
  assert.equal(a.headers.date_utc, null);
  assert.equal(a.unreadable.date, "MAIL_DATE_UNREADABLE");
});
